en.referenceSolution:
using System.Diagnostics;
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

var builder = WebApplication.CreateBuilder(args);

// One place for cross-cutting ProblemDetails fields: used by UseExceptionHandler,
// UseStatusCodePages and every IProblemDetailsService.TryWriteAsync call below.
builder.Services.AddProblemDetails(options =>
{
    options.CustomizeProblemDetails = ctx =>
    {
        var request = ctx.HttpContext.Request;
        ctx.ProblemDetails.Instance = $"{request.Method} {request.Path}";
        ctx.ProblemDetails.Extensions.TryAdd("traceId", Activity.Current?.Id ?? ctx.HttpContext.TraceIdentifier);
    };
});

// Invoked in registration order until one returns true: specific first, catch-all last.
builder.Services.AddExceptionHandler<DomainExceptionHandler>();
builder.Services.AddExceptionHandler<FallbackExceptionHandler>();

var app = builder.Build();

app.UseExceptionHandler();   // first: it only sees exceptions thrown by what is registered after it
app.UseStatusCodePages();    // bare 4xx/5xx (e.g. unmatched route) get the same ProblemDetails shape

app.MapGet("/orders/{id:int}", (int id) =>
    id == 1 ? Results.Ok(new { id, status = "open" }) : throw new NotFoundException("Order", id));

app.MapPost("/orders/{id:int}/ship", (int id) =>
{
    throw new ConflictException($"Order {id} has already been shipped.");
});

app.MapPost("/orders/{id:int}/discount", (int id) =>
{
    throw new BusinessRuleException("discount.limit", $"Order {id} cannot be discounted by more than 30%.");
});

app.MapPost("/customers", () =>
{
    throw new DomainValidationException(new Dictionary<string, string[]>
    {
        ["email"] = ["'email' must be a valid e-mail address."],
        ["name"] = ["'name' must not be empty."],
    });
});

app.MapGet("/boom", () =>
{
    throw new InvalidOperationException("Connection string 'Orders' points to db-prod-7.internal.");
});

app.Run();

// ---------------------------------------------------------------- domain exceptions

public abstract class DomainException(string message) : Exception(message);

public sealed class NotFoundException(string resource, object key)
    : DomainException($"{resource} '{key}' was not found.")
{
    public string Resource { get; } = resource;
    public object Key { get; } = key;
}

public sealed class ConflictException(string message) : DomainException(message);

public sealed class BusinessRuleException(string code, string message) : DomainException(message)
{
    public string Code { get; } = code;
}

public sealed class DomainValidationException(IReadOnlyDictionary<string, string[]> errors)
    : DomainException("One or more validation errors occurred.")
{
    public IReadOnlyDictionary<string, string[]> Errors { get; } = errors;
}

// ---------------------------------------------------------------- handlers (singletons)

public sealed class DomainExceptionHandler(
    IProblemDetailsService problemDetails,
    ILogger<DomainExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        if (exception is not DomainException domain)
            return false;   // not ours: let the next handler decide

        ProblemDetails problem = domain switch
        {
            NotFoundException e => new ProblemDetails
            {
                Status = StatusCodes.Status404NotFound,
                Detail = e.Message,
            },
            ConflictException e => new ProblemDetails
            {
                Status = StatusCodes.Status409Conflict,
                Detail = e.Message,
            },
            BusinessRuleException e => new ProblemDetails
            {
                Status = StatusCodes.Status422UnprocessableEntity,
                Title = "Business rule violated",
                Detail = e.Message,
                Extensions = { ["code"] = e.Code },
            },
            DomainValidationException e => new HttpValidationProblemDetails(new Dictionary<string, string[]>(e.Errors))
            {
                Status = StatusCodes.Status400BadRequest,
                Detail = e.Message,
            },
            _ => new ProblemDetails
            {
                Status = StatusCodes.Status422UnprocessableEntity,
                Detail = domain.Message,
            },
        };

        logger.LogInformation("Domain error {ErrorType} for {Method} {Path}: {Message}",
            domain.GetType().Name, httpContext.Request.Method, httpContext.Request.Path, domain.Message);

        // The default writer derives type/title from the response status, so set it first.
        httpContext.Response.StatusCode = problem.Status!.Value;
        await problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            ProblemDetails = problem,
            Exception = exception,
        });
        return true;   // handled even if Accept ruled out a JSON body: the status code still goes out
    }
}

public sealed class FallbackExceptionHandler(
    IProblemDetailsService problemDetails,
    IHostEnvironment environment,
    ILogger<FallbackExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        // .NET 10 suppresses the middleware's own diagnostics for exceptions a handler reports as
        // handled, so the handler that turns this into a 500 is also the one that records it.
        logger.LogError(exception, "Unhandled exception for {Method} {Path}",
            httpContext.Request.Method, httpContext.Request.Path);

        httpContext.Response.StatusCode = StatusCodes.Status500InternalServerError;
        await problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            Exception = exception,
            ProblemDetails = new ProblemDetails
            {
                Status = StatusCodes.Status500InternalServerError,
                Title = "An unexpected error occurred.",
                // Never leak internals (SQL, hosts, stack traces) outside Development.
                Detail = environment.IsDevelopment() ? exception.ToString() : null,
            },
        });
        return true;
    }
}

