using System.Collections.Concurrent;
using System.Net.Http.Json;
using System.Security.Cryptography;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton(TimeProvider.System);
builder.Services.AddSingleton<IIdempotencyStore>(sp =>
    new InMemoryIdempotencyStore(sp.GetRequiredService<TimeProvider>(), TimeSpan.FromHours(24)));

var app = builder.Build();
app.Urls.Add("http://127.0.0.1:0");

// In a real app: after UseExceptionHandler and UseAuthentication (keys are scoped per user).
app.UseMiddleware<IdempotencyMiddleware>();

var paymentsCreated = 0;
app.MapPost("/payments", async (PaymentRequest request) =>
{
    await Task.Delay(200);   // long enough for concurrent duplicates to overlap
    var id = Interlocked.Increment(ref paymentsCreated);
    return Results.Created($"/payments/{id}", new { id, request.Amount, request.Currency });
});

var flakyCalls = 0;
app.MapPost("/flaky", () =>
    Interlocked.Increment(ref flakyCalls) == 1 ? Results.StatusCode(503) : Results.Ok(new { ok = true }));

await app.StartAsync();
using var client = new HttpClient { BaseAddress = new Uri(app.Urls.First()) };
var failures = 0;
var payment = new { amount = 10.5m, currency = "EUR" };

// 1. Sequential duplicate is replayed, the endpoint runs once.
var first = await Post("/payments", payment, "key-1");
var second = await Post("/payments", payment, "key-1");
Check("replay",
    first.StatusCode == System.Net.HttpStatusCode.Created
    && second.StatusCode == System.Net.HttpStatusCode.Created
    && await first.Content.ReadAsStringAsync() == await second.Content.ReadAsStringAsync()
    && first.Headers.Location == second.Headers.Location
    && second.Headers.Contains("Idempotent-Replayed")
    && Volatile.Read(ref paymentsCreated) == 1);

// 2. Same key, different payload.
var mismatch = await Post("/payments", new { amount = 99m, currency = "EUR" }, "key-1");
Check("fingerprint mismatch -> 422", (int)mismatch.StatusCode == 422);

// 3. Concurrent duplicates: one runs, one is told to retry.
var concurrent = await Task.WhenAll(Post("/payments", payment, "key-2"), Post("/payments", payment, "key-2"));
var codes = concurrent.Select(r => (int)r.StatusCode).Order().ToArray();
Check("concurrent duplicate -> 409", codes is [201, 409]);

// 4. No key: no idempotency.
var before = Volatile.Read(ref paymentsCreated);
await Post("/payments", payment, null);
await Post("/payments", payment, null);
Check("no key -> both executed", Volatile.Read(ref paymentsCreated) == before + 2);

// 5. 5xx releases the key so the retry runs again.
var flaky1 = await Post("/flaky", new { }, "key-3");
var flaky2 = await Post("/flaky", new { }, "key-3");
Check("5xx not stored", (int)flaky1.StatusCode == 503 && (int)flaky2.StatusCode == 200
                        && !flaky2.Headers.Contains("Idempotent-Replayed"));

// 6. Invalid key.
var invalid = await Post("/payments", payment, new string('k', 300));
Check("invalid key -> 400", (int)invalid.StatusCode == 400);

Console.WriteLine(failures == 0 ? "ALL PASSED" : $"{failures} FAILED");
await app.StopAsync();

async Task<HttpResponseMessage> Post(string path, object body, string? key)
{
    using var message = new HttpRequestMessage(HttpMethod.Post, path) { Content = JsonContent.Create(body) };
    if (key is not null) message.Headers.Add(IdempotencyMiddleware.HeaderName, key);
    var response = await client.SendAsync(message);
    await response.Content.LoadIntoBufferAsync();
    return response;
}

void Check(string name, bool ok)
{
    if (!ok) failures++;
    Console.WriteLine($"{(ok ? "PASS" : "FAIL")} {name}");
}

// ------------------------------------------------------------------ contracts

public sealed record PaymentRequest(decimal Amount, string Currency);

public sealed record CachedResponse(
    int StatusCode, string? ContentType, IReadOnlyDictionary<string, string> Headers, byte[] Body);

public enum BeginOutcome { Acquired, InProgress, Completed, FingerprintMismatch }

public readonly record struct BeginResult(BeginOutcome Outcome, CachedResponse? Response = null);

public interface IIdempotencyStore
{
    /// Atomically reserves <paramref name="key"/> or reports the state of an existing reservation.
    ValueTask<BeginResult> TryBeginAsync(string key, string fingerprint, CancellationToken ct);

    /// Stores the final response for a reservation owned by the caller.
    ValueTask CompleteAsync(string key, CachedResponse response, CancellationToken ct);

    /// Drops an in-flight reservation so a retry can execute again.
    ValueTask ReleaseAsync(string key, CancellationToken ct);
}

// ------------------------------------------------------------------ in-memory store (single instance only)

public sealed class InMemoryIdempotencyStore(TimeProvider clock, TimeSpan ttl) : IIdempotencyStore
{
    private sealed record Entry(string Fingerprint, CachedResponse? Response, DateTimeOffset ExpiresAt);

    private readonly ConcurrentDictionary<string, Entry> _entries = new();

    public ValueTask<BeginResult> TryBeginAsync(string key, string fingerprint, CancellationToken ct)
    {
        var now = clock.GetUtcNow();
        var fresh = new Entry(fingerprint, null, now + ttl);

        while (true)
        {
            var current = _entries.GetOrAdd(key, fresh);
            if (ReferenceEquals(current, fresh))
                return ValueTask.FromResult(new BeginResult(BeginOutcome.Acquired));

            if (current.ExpiresAt <= now)
            {
                // Expired: compare-and-swap; if another request replaced it first, re-evaluate.
                if (_entries.TryUpdate(key, fresh, current))
                    return ValueTask.FromResult(new BeginResult(BeginOutcome.Acquired));
                continue;
            }

            if (!string.Equals(current.Fingerprint, fingerprint, StringComparison.Ordinal))
                return ValueTask.FromResult(new BeginResult(BeginOutcome.FingerprintMismatch));

            return ValueTask.FromResult(current.Response is null
                ? new BeginResult(BeginOutcome.InProgress)
                : new BeginResult(BeginOutcome.Completed, current.Response));
        }
    }

    public ValueTask CompleteAsync(string key, CachedResponse response, CancellationToken ct)
    {
        if (_entries.TryGetValue(key, out var current) && current.Response is null)
            _entries.TryUpdate(key, current with { Response = response, ExpiresAt = clock.GetUtcNow() + ttl }, current);
        return ValueTask.CompletedTask;
    }

    public ValueTask ReleaseAsync(string key, CancellationToken ct)
    {
        // Remove only our in-flight entry, never a completed one written in the meantime.
        if (_entries.TryGetValue(key, out var current) && current.Response is null)
            _entries.TryRemove(KeyValuePair.Create(key, current));
        return ValueTask.CompletedTask;
    }
}

// ------------------------------------------------------------------ middleware

public sealed class IdempotencyMiddleware(
    RequestDelegate next,
    IIdempotencyStore store,
    ILogger<IdempotencyMiddleware> logger)
{
    public const string HeaderName = "Idempotency-Key";
    private const int MaxKeyLength = 255;
    private static readonly string[] ReplayedHeaders = ["Location", "ETag"];

    public async Task InvokeAsync(HttpContext context)
    {
        var request = context.Request;
        if (!(HttpMethods.IsPost(request.Method) || HttpMethods.IsPatch(request.Method))
            || !request.Headers.TryGetValue(HeaderName, out var values))
        {
            await next(context);
            return;
        }

        var rawKey = values.ToString();
        if (values.Count != 1 || !IsValidKey(rawKey))
        {
            await Results.Problem(statusCode: StatusCodes.Status400BadRequest,
                title: $"Invalid {HeaderName} header.").ExecuteAsync(context);
            return;
        }

        var ct = context.RequestAborted;
        var key = $"{context.User.Identity?.Name ?? "anonymous"}|{rawKey}";
        var fingerprint = await FingerprintAsync(request, ct);

        var begin = await store.TryBeginAsync(key, fingerprint, ct);
        switch (begin.Outcome)
        {
            case BeginOutcome.FingerprintMismatch:
                await Results.Problem(statusCode: StatusCodes.Status422UnprocessableEntity,
                    title: $"{HeaderName} was already used with a different request.").ExecuteAsync(context);
                return;

            case BeginOutcome.InProgress:
                context.Response.Headers.RetryAfter = "1";
                await Results.Problem(statusCode: StatusCodes.Status409Conflict,
                    title: $"A request with this {HeaderName} is still being processed.").ExecuteAsync(context);
                return;

            case BeginOutcome.Completed:
                logger.LogInformation("Replaying stored response for idempotency key {Key}", rawKey);
                await ReplayAsync(context, begin.Response!, ct);
                return;
        }

        // Acquired: run the endpoint once, capturing the body so it can be stored.
        var originalBody = context.Response.Body;
        using var buffer = new MemoryStream();
        context.Response.Body = buffer;
        var stored = false;
        try
        {
            await next(context);

            var response = context.Response;
            if (response.StatusCode < StatusCodes.Status500InternalServerError)
            {
                var headers = ReplayedHeaders
                    .Where(h => response.Headers.ContainsKey(h))
                    .ToDictionary(h => h, h => response.Headers[h].ToString());
                await store.CompleteAsync(key,
                    new CachedResponse(response.StatusCode, response.ContentType, headers, buffer.ToArray()),
                    CancellationToken.None);
                stored = true;
            }

            context.Response.Body = originalBody;
            buffer.Position = 0;
            await buffer.CopyToAsync(originalBody, ct);
        }
        finally
        {
            context.Response.Body = originalBody;
            if (!stored)   // 5xx or exception: let the client retry for real
                await store.ReleaseAsync(key, CancellationToken.None);
        }
    }

    private static bool IsValidKey(string key) =>
        key.Length is > 0 and <= MaxKeyLength
        && key.All(c => char.IsAsciiLetterOrDigit(c) || c is '-' or '_');

    private static async Task<string> FingerprintAsync(HttpRequest request, CancellationToken ct)
    {
        request.EnableBuffering();   // seekable copy, so the endpoint can read the body again
        var bodyHash = await SHA256.HashDataAsync(request.Body, ct);
        request.Body.Position = 0;
        return $"{request.Method} {request.Path}{request.QueryString} {Convert.ToHexString(bodyHash)}";
    }

    private static async Task ReplayAsync(HttpContext context, CachedResponse cached, CancellationToken ct)
    {
        context.Response.StatusCode = cached.StatusCode;
        if (cached.ContentType is not null)
            context.Response.ContentType = cached.ContentType;
        foreach (var (name, value) in cached.Headers)
            context.Response.Headers[name] = value;
        context.Response.Headers["Idempotent-Replayed"] = "true";
        await context.Response.Body.WriteAsync(cached.Body, ct);
    }
}

en.note:
## What it is

Both middleware and filters implement cross-cutting behaviour around request handling. The difference is **where they sit and what they can see**:

- **Middleware** runs in the application pipeline for every request that reaches its position — static files, health checks, 404s, every programming model. It sees `HttpContext` (and, after `UseRouting`, the selected endpoint and its metadata). It knows nothing about action arguments, model state or results.
- **MVC filters** run *inside* endpoint execution, only for controller actions (and Razor Pages), within the action invocation. They see `ActionContext`: route data, the action descriptor, bound arguments, `ModelState`, the `IActionResult`.
- **Endpoint filters** (`IEndpointFilter`, .NET 7+) are the minimal-API counterpart: they wrap a route handler after parameter binding and see the bound arguments and the handler's return value.

## How filters work underneath

The MVC `ResourceInvoker`/`ControllerActionInvoker` runs a fixed sequence for the selected action:

1. **Authorization filters** (`IAuthorizationFilter`) — can short-circuit before anything else. (`[Authorize]` itself is enforced by the authorization *middleware* under endpoint routing.)
2. **Resource filters** — before model binding; good for short-circuiting caches or disabling form value providers.
3. Model binding and validation.
4. **Action filters** — around the action method; see and can change `ActionArguments`, inspect `ModelState`, replace the result. `[ApiController]`'s automatic 400 is an action filter.
5. The action.
6. **Exception filters** — handle exceptions from controller creation, model binding, action filters and the action. They do **not** catch exceptions from resource filters, result filters or result execution.
7. **Result filters** — around execution of the `IActionResult`. They run only when the action or an action filter produced a result; a short-circuit from an authorization or resource filter, or a result set by an exception filter, skips them unless the filter implements `IAlwaysRunResultFilter`.

Scope order: global → controller → action on the way in, reverse on the way out; `IOrderedFilter.Order` overrides it. Filter attributes are metadata instances shared across requests — keep them stateless. For DI use `[ServiceFilter(typeof(T))]` (resolved from DI, `T` must be registered) or `[TypeFilter(typeof(T))]` (created via `ActivatorUtilities`).

**Endpoint filters** form a chain in front of the handler: the first one added is the outermost, so execution is first-in on the way in and last-out on the way out; filters on a route group run before filters on the endpoint. `EndpointFilterInvocationContext.Arguments` holds the bound arguments (`GetArgument<T>(index)`); returning without calling `next` short-circuits. `AddEndpointFilterFactory` lets a filter inspect the handler's `MethodInfo` once at startup and skip itself where irrelevant — the way to keep per-request overhead near zero.

## Choosing

| Need | Put it in |
|---|---|
| Applies to all requests, including non-endpoint ones (security headers, compression, correlation id, exception handling) | Middleware |
| Needs only HTTP data but should be opt-in per endpoint | Middleware reading endpoint metadata after `UseRouting` (how authorization, CORS, rate limiting and output caching work) |
| Needs bound arguments, `ModelState` or the action result (validation, argument-level auditing, result wrapping) | Action / endpoint filter |
| Must run before model binding for MVC (short-circuit caching, request size tweaks) | Resource filter |
| Exception mapping | Global `IExceptionHandler` middleware; exception filters only if MVC-specific context is needed |

```csharp
// Endpoint filter: sees bound arguments — impossible in middleware without re-reading the body.
app.MapPost("/orders", (CreateOrder cmd, IOrderService svc) => svc.CreateAsync(cmd))
   .AddEndpointFilter(async (ctx, next) =>
   {
       var cmd = ctx.GetArgument<CreateOrder>(0);
       if (cmd.Lines.Count > 100)
           return TypedResults.Problem("Too many lines.", statusCode: StatusCodes.Status422UnprocessableEntity);
       return await next(ctx);
   });

// Middleware: opt-in via endpoint metadata, works for controllers, minimal APIs and FastEndpoints alike.
app.UseRouting();
app.Use(async (HttpContext ctx, RequestDelegate next) =>
{
    if (ctx.GetEndpoint()?.Metadata.GetMetadata<RequireTenantAttribute>() is not null
        && !ctx.Request.Headers.ContainsKey("X-Tenant"))
    {
        ctx.Response.StatusCode = StatusCodes.Status400BadRequest;
        return;
    }
    await next(ctx);
});
```

## What an interviewer probes

- The MVC filter order and what each stage can see.
- Which exceptions an exception filter does not catch, and why global handling belongs in middleware.
- Why result filters sometimes "don't run" (short-circuits) and `IAlwaysRunResultFilter`.
- Endpoint filter ordering and how they get at bound arguments.

## Common misconceptions

- "Filters are faster middleware" — they are a different layer with more context, and they exist only inside MVC/minimal-API endpoint execution.
- "Middleware cannot be endpoint-specific" — after `UseRouting` it can read endpoint metadata.
- "MVC action filters work on minimal APIs" — minimal handlers ignore MVC filter attributes; use `IEndpointFilter`.

uk.note:
## Що це

І middleware, і filters реалізують наскрізну поведінку навколо обробки запиту. Різниця в тому, **де вони розташовані і що бачать**:

- **Middleware** виконується в pipeline застосунку для кожного запиту, що доходить до його позиції, — static files, health checks, 404, будь-яка модель програмування. Він бачить `HttpContext` (а після `UseRouting` — вибраний endpoint і його метадані). Про аргументи action, model state чи результати він нічого не знає.
- **MVC filters** виконуються *всередині* виконання endpoint-а, лише для controller actions (і Razor Pages), у межах виклику action. Вони бачать `ActionContext`: route data, action descriptor, зв'язані аргументи, `ModelState`, `IActionResult`.
- **Endpoint filters** (`IEndpointFilter`, .NET 7+) — аналог для minimal APIs: вони обгортають route handler після parameter binding і бачать зв'язані аргументи та значення, яке повертає handler.

## Як filters працюють під капотом

MVC `ResourceInvoker`/`ControllerActionInvoker` виконує фіксовану послідовність для вибраного action:

1. **Authorization filters** (`IAuthorizationFilter`) — можуть зробити short-circuit раніше за все інше. (Сам `[Authorize]` за endpoint routing застосовує authorization *middleware*.)
2. **Resource filters** — до model binding; підходять для short-circuit кешування або вимкнення form value providers.
3. Model binding і validation.
4. **Action filters** — навколо методу action; бачать і можуть змінювати `ActionArguments`, перевіряти `ModelState`, замінювати результат. Автоматичний 400 від `[ApiController]` — це action filter.
5. Сам action.
6. **Exception filters** — обробляють винятки зі створення controller-а, model binding, action filters і action. Вони **не** перехоплюють винятки з resource filters, result filters чи виконання результату.
7. **Result filters** — навколо виконання `IActionResult`. Вони виконуються лише тоді, коли результат створив action або action filter; short-circuit з authorization чи resource filter або результат, встановлений exception filter, їх оминає, якщо тільки filter не реалізує `IAlwaysRunResultFilter`.

Порядок за scope: global → controller → action на шляху всередину, зворотний на шляху назовні; `IOrderedFilter.Order` це перевизначає. Атрибути фільтрів — це екземпляри метаданих, спільні для всіх запитів, — тримайте їх без стану. Для DI використовуйте `[ServiceFilter(typeof(T))]` (резолвиться з DI, `T` має бути зареєстрований) або `[TypeFilter(typeof(T))]` (створюється через `ActivatorUtilities`).

**Endpoint filters** утворюють ланцюжок перед handler-ом: перший доданий — найзовнішніший, тож виконання — first-in на шляху всередину і last-out на шляху назовні; filters на route group виконуються перед filters на endpoint-і. `EndpointFilterInvocationContext.Arguments` містить зв'язані аргументи (`GetArgument<T>(index)`); повернення без виклику `next` — це short-circuit. `AddEndpointFilterFactory` дозволяє filter-у один раз на старті проаналізувати `MethodInfo` handler-а і не підключатися там, де він нерелевантний, — так накладні витрати на запит лишаються близькими до нуля.

## Як обирати

| Потреба | Куди це покласти |
|---|---|
| Стосується всіх запитів, включно з тими, що не йдуть до endpoint-ів (security headers, compression, correlation id, exception handling) | Middleware |
| Потребує лише HTTP-даних, але має вмикатися для окремих endpoint-ів | Middleware, що читає метадані endpoint-а після `UseRouting` (так працюють authorization, CORS, rate limiting і output caching) |
| Потребує зв'язаних аргументів, `ModelState` або результату action (validation, аудит на рівні аргументів, обгортання результату) | Action / endpoint filter |
| Має виконуватися до model binding у MVC (short-circuit кешування, налаштування розміру запиту) | Resource filter |
| Мапінг винятків | Глобальний middleware з `IExceptionHandler`; exception filters — лише якщо потрібен специфічний для MVC контекст |

```csharp
// Endpoint filter: sees bound arguments — impossible in middleware without re-reading the body.
app.MapPost("/orders", (CreateOrder cmd, IOrderService svc) => svc.CreateAsync(cmd))
   .AddEndpointFilter(async (ctx, next) =>
   {
       var cmd = ctx.GetArgument<CreateOrder>(0);
       if (cmd.Lines.Count > 100)
           return TypedResults.Problem("Too many lines.", statusCode: StatusCodes.Status422UnprocessableEntity);
       return await next(ctx);
   });

// Middleware: opt-in via endpoint metadata, works for controllers, minimal APIs and FastEndpoints alike.
app.UseRouting();
app.Use(async (HttpContext ctx, RequestDelegate next) =>
{
    if (ctx.GetEndpoint()?.Metadata.GetMetadata<RequireTenantAttribute>() is not null
        && !ctx.Request.Headers.ContainsKey("X-Tenant"))
    {
        ctx.Response.StatusCode = StatusCodes.Status400BadRequest;
        return;
    }
    await next(ctx);
});
```

## Що перевіряє інтерв'юер

- Порядок MVC filters і що бачить кожен етап.
- Які винятки exception filter не перехоплює і чому глобальна обробка належить middleware.
- Чому result filters іноді "не виконуються" (short-circuits) і `IAlwaysRunResultFilter`.
- Порядок endpoint filters і як вони отримують доступ до зв'язаних аргументів.

## Поширені хибні уявлення

- "Filters — це швидші middleware" — це інший шар із ширшим контекстом, і вони існують лише всередині виконання endpoint-ів MVC/minimal API.
- "Middleware не може бути специфічним для endpoint-а" — після `UseRouting` він може читати метадані endpoint-а.
- "MVC action filters працюють на minimal APIs" — minimal handler-и ігнорують атрибути MVC-фільтрів; використовуйте `IEndpointFilter`.
